  camEvent.release = release;
  camEvent.zoomAmp = zoomAmp;
  camEvent.thetaAmp = thetaAmp;
  camEvent.phiAmp = phiAmp;
  camEvent.rollAmp = rollAmp;
  camEvent.mode = mode;
  camEvent.combo = combo;
  camEvent.phase = idx * 2.399963 + (snapTone - lowTone) * 1.4;
  camEvent.low = lowTone;
  camEvent.body = bodyTone;
  camEvent.snap = snapTone;
