  img.decoding = 'async';
  if (!isDataUrl && /^https?:\/\//i.test(dataUrl)) img.crossOrigin = 'anonymous';
  img.onload = function() {
    if (!coverApplyStillCurrent(opts)) return;
    var cv = makeSquareCoverCanvas(img, coverTextureSizeForResolution(fx.coverResolution));
    setAlbumBackground(dataUrl);
    applyCoverCanvas(cv, dataUrl, Object.assign({}, opts, { coverSourceKind: isDataUrl ? 'data' : 'url', coverSource: dataUrl }));
  };
  img.onerror = function() {
    // data URL 解码失败时保留现有封面，不强行清空，只记录以便排查损坏的本地封面缓存。
    img.onload = null;
    img.onerror = null;
    console.warn('cover data url decode failed');
  };
  img.src = dataUrl;
