function collectPlaylistActionTitle(playlist, song, contained) {
  var name = String(playlist && playlist.name || '未命名歌单');
  if (!song) return name;
  return (contained ? '已收藏到「' : '收藏到「') + name + '」';
}
function renderCollectModal() {
  var title = document.getElementById('collect-modal-title');
  var current = document.getElementById('collect-current');
  var list = document.getElementById('collect-list');
  var input = document.getElementById('collect-new-name');
  if (!current || !list) return;
  var song = collectTargetSong;
  if (title) title.textContent = song ? '选择收藏到任意歌单' : '新建本地歌单';
  if (input) input.placeholder = song ? '新建歌单并收藏到该歌单' : '新建歌单名称';
  current.style.display = song ? '' : 'none';
  if (song) {
    var cover = songCoverSrc(song, 80);
    current.innerHTML = (cover ? '<img src="' + escHtml(cover) + '" alt="">' : '<div class="cover-placeholder"></div>') +
      '<div style="min-width:0"><div class="collect-title">' + escHtml(song.name || '当前歌曲') + '</div><div class="collect-sub">' + escHtml(songDisplaySubtitle(song)) + '</div></div>';
  } else {
    current.innerHTML = '';
  }
  var playlists = readLocalPlaylists();
  if (!playlists.length) {
    list.innerHTML = '<div class="collect-empty">还没有独立歌单，在上方输入名称即可创建</div>';
    return;
  }
  var html = '';
  for (var i = 0; i < playlists.length; i++) {
    var pl = playlists[i];
    var resolvedSongs = getLocalPlaylistSongsById(pl.id);
    var thumb = resolvedSongs.length ? songCoverSrc(resolvedSongs[0], 80) : '';
    var contained = !!(song && localPlaylistHasSong(pl.id, song));
    var actionTitle = collectPlaylistActionTitle(pl, song, contained);
    html += '<div class="collect-item' + (contained ? ' added' : '') + '" data-collect-pid="' + escHtml(String(pl.id || '')) + '" onclick="addCollectTargetToPlaylist(this.getAttribute(\'data-collect-pid\'))">' +
      (thumb ? '<img src="' + escHtml(thumb) + '" alt="">' : '<div class="cover-placeholder"></div>') +
      '<div style="min-width:0;flex:1"><div class="collect-title">' + escHtml(actionTitle) + '</div><div class="collect-sub">' + pl.songRefs.length + ' 首' + (contained ? ' · 已在此歌单' : (song ? ' · 点击收藏' : ' · 点击打开')) + '</div></div>' +
      (contained ? '<span class="collect-added-mark">✓</span>' : '') +
    '</div>';
  }
  list.innerHTML = html;
  if (window.gsap) animateListItems(list, '.collect-item', { x: 0, y: 6, stagger: 0.012, duration: 0.18, limit: 18 });
}
function setCollectBusyPid(pid, busy) {
  var list = document.getElementById('collect-list');
  if (!list) return;
  list.querySelectorAll('.collect-item').forEach(function(item){
    item.classList.toggle('busy', !!busy && item.getAttribute('data-collect-pid') === String(pid));
  });
}
async function createPlaylistFromCollect() {
  if (collectBusy) return;
  var input = document.getElementById('collect-new-name');
  var name = input ? localPlaylistName(input.value) : '';
  if (!name) {
    showToast('先输入歌单名称');
    if (input) input.focus();
    return;
  }
  collectBusy = true;
  updateLikeButtons();
  var playlist = createLocalPlaylist(name, collectTargetSong);
  collectBusy = false;
  updateLikeButtons();
  if (!playlist) {
    showToast('歌单创建失败');
    return;
  }
  if (input) input.value = '';
  showToast(collectTargetSong ? '已创建「' + playlist.name + '」并收藏歌曲' : '已创建歌单「' + playlist.name + '」');
  if (collectTargetSong) closeCollectModal();
  else renderCollectModal();
}
function collectResultMessage(r) {
  return r ? '已收藏到歌单' : '歌曲已在歌单中';
}
async function verifySongInPlaylist(pid, songId) {
  return !!(collectTargetSong && localPlaylistHasSong(pid, collectTargetSong));
}
async function addCollectTargetToPlaylist(pid) {
  var playlist = localPlaylistById(pid);
  if (!playlist) {
    showToast('歌单不存在或已删除');
    renderCollectModal();
    return;
  }
  if (!collectTargetSong) {
    closeCollectModal();
    selectLocalPlaylist(pid);
    showLocalPlaylistPanelAutoHide();
    return;
  }
  if (collectBusy) return;
  if (localPlaylistHasSong(pid, collectTargetSong)) {
    showToast('已收藏到「' + playlist.name + '」');
    return;
  }
  collectBusy = true;
  setCollectBusyPid(pid, true);
  updateLikeButtons();
  var added = addSongToLocalPlaylist(pid, collectTargetSong);
  collectBusy = false;
  setCollectBusyPid(pid, false);
  updateLikeButtons();
  renderCollectModal();
  showToast(added ? '已收藏到「' + playlist.name + '」' : '歌曲已在歌单中');
}
/**
 * 克隆歌曲对象并套用自定义封面。入队路径会批量调用，单首逻辑保持集中，避免各入口重复拼字段。
 * @param {object} song 原始歌曲对象。
 * @returns {object} 可安全写入播放队列的歌曲副本。
 */
function cloneSong(song){
  var copy = Object.assign({}, song);
  var fullCover = copy.localCoverDataUrl;
  delete copy.localCoverDataUrl;
  // 在途任务只归源对象所有；副本若继承 Promise，源任务完成后无法清理副本状态。
  delete copy.localMetadataPromise;
  delete copy.localCoverPromise;
  delete copy.localLyricPromise;
  delete copy.localLyricCachePromise;
  delete copy.localCoverLoading;
  delete copy.localLyricLoading;
  if (fullCover && copy.customCover === fullCover) delete copy.customCover;
  invalidateSongCoverCache(copy);
  return hydrateCustomCover(copy);
}
/**
 * 批量克隆歌曲列表。大本地库或大歌单入队时用显式循环减少 map 回调开销，并保持数组长度语义。
 * @param {Array<object>} songs 原始歌曲列表。
 * @returns {Array<object>} 歌曲副本列表。
 */
function cloneSongList(songs) {
  var source = Array.isArray(songs) ? songs : [];
  var list = new Array(source.length);
  for (var i = 0; i < source.length; i++) {
    if (Object.prototype.hasOwnProperty.call(source, i)) list[i] = cloneSong(source[i]);
  }
  return list;
}
function avatarSrc(url) {
  if (!url) return '';
  return coverProxySrc(url, true);
}

