var searchTimer = null;
var searchRequestSeq = 0;
var searchLastResultQuery = '';
var SEARCH_HISTORY_STORE_KEY = 'mineradio-search-history';
var searchHistoryCache = null;
var $input = document.getElementById('search-input');
var $results = document.getElementById('search-results');
var $loading = document.getElementById('loading-overlay');
function syncSearchAreaResultState() {
  var searchArea = document.getElementById('search-area');
  if (!searchArea || !$results) return;
  var hasVisibleResults = $results.classList.contains('show') && $results.children.length > 0;
  var hasIntent = !!($input && String($input.value || '').trim());
  searchArea.classList.toggle('has-results', hasVisibleResults && hasIntent);
}
if (window.MutationObserver && $results) {
  new MutationObserver(syncSearchAreaResultState).observe($results, { childList: true, attributes: true, attributeFilter: ['class'] });
}
function isMusicSearchMode(mode) {
  return true;
}
function searchResultKey(q, mode) {
  return (mode || searchMode || 'song') + '|' + String(q || '').trim();
}
function clearSearchResults() {
  searchRequestSeq++;
  searchLastResultQuery = '';
  searchResultsLastDomSignature = '';
  playlist = [];
  $results.innerHTML = '';
  $results.classList.remove('show');
}
function refreshVisibleLocalLibraryResults(q) {
  if (!$results || !$input || !$results.classList.contains('show')) return false;
  renderLocalLibraryResults(q == null ? ($input.value || '') : q);
  return true;
}
/**
 * 复制并清洗搜索历史。搜索历史最多展示 10 条，限量循环避免读取时创建 map/filter/slice 中间数组。
 * @param {Array<string>} source 搜索历史来源。
 * @param {number} limit 最大保留条数。
 * @returns {Array<string>} 清洗后的搜索历史。
 */
function compactSearchHistoryItems(source, limit) {
  var items = [];
  source = Array.isArray(source) ? source : [];
  limit = Math.max(0, Number(limit) || 0);
  for (var i = 0; i < source.length && items.length < limit; i++) {
    var value = String(source[i] || '').trim();
    if (value) items.push(value);
  }
  return items;
}
/**
 * 读取搜索历史。连续打开搜索面板会重复走这里，因此优先复用内存缓存并只返回小数组副本。
 * @returns {Array<string>} 最多 10 条搜索历史。
 */
function readSearchHistory() {
  if (searchHistoryCache) return compactSearchHistoryItems(searchHistoryCache, 10);
  try {
    var raw = JSON.parse(localStorage.getItem(SEARCH_HISTORY_STORE_KEY) || '[]');
    searchHistoryCache = compactSearchHistoryItems(raw, 10);
    return compactSearchHistoryItems(searchHistoryCache, 10);
  } catch (e) {
    searchHistoryCache = [];
    return [];
  }
}
/**
 * 写入搜索历史。写入时同步刷新内存缓存，避免后续打开搜索面板再次解析 localStorage。
 * @param {Array<string>} items 新的搜索历史列表。
 * @returns {void}
 */
function writeSearchHistory(items) {
  searchHistoryCache = compactSearchHistoryItems(items, 10);
  try { localStorage.setItem(SEARCH_HISTORY_STORE_KEY, JSON.stringify(searchHistoryCache)); } catch (e) {}
}
/**
 * 记录搜索词。该路径在每次成功搜索后触发，用单次循环完成去重和限量。
 * @param {string} q 搜索关键词。
 * @returns {void}
 */
function rememberSearchQuery(q) {
  q = String(q || '').trim();
  if (!q) return;
  var previous = readSearchHistory();
  var queryKey = q.toLowerCase();
  var items = [q];
  for (var i = 0; i < previous.length && items.length < 10; i++) {
    if (previous[i].toLowerCase() !== queryKey) items.push(previous[i]);
  }
  writeSearchHistory(items);
}
function renderSearchHistory() {
  if (searchMode !== 'song') return false;
  var items = readSearchHistory();
  if (!items.length) {
    searchResultsLastDomSignature = '';
    $results.innerHTML = '';
    $results.classList.remove('show');
    return false;
  }
  searchResultsLastDomSignature = '';
  $results.innerHTML =
    '<div class="search-history">' +
      '<div class="search-history-head"><span>搜索历史</span><button class="search-history-clear" type="button" data-clear-history="1">清空</button></div>' +
      '<div class="search-history-list">' +
        items.map(function(q){ return '<button class="search-history-chip" type="button" data-history-query="' + escHtml(q) + '">' + escHtml(q) + '</button>'; }).join('') +
      '</div>' +
    '</div>';
  $results.classList.add('show');
  scheduleGlassDisplacementMapUpdate('searchPill');
  return true;
}
function clearSearchHistory() {
  writeSearchHistory([]);
  renderSearchHistory();
}
function runSearchHistory(q) {
  q = String(q || '').trim();
  if (!q) return;
  $input.value = q;
  setPeek(document.getElementById('search-area'), true, 'search');
  doSearch(q);
  $input.focus();
}
function updateSearchModeTabs() {
  var songBtn = document.getElementById('search-mode-song');
  if (songBtn) {
    songBtn.classList.toggle('active', searchMode === 'song');
    songBtn.setAttribute('aria-selected', searchMode === 'song' ? 'true' : 'false');
  }
  if ($input) {
    $input.placeholder = '搜索本地歌曲、歌手、文件名...';
  }
  scheduleGlassDisplacementMapUpdate('searchPill');
}
function setSearchMode(mode) {
  mode = 'song';
  if (searchMode === mode) return;
  searchMode = mode;
  updateSearchModeTabs();
  clearSearchResults();
  var searchArea = document.getElementById('search-area');
  if (searchArea) setPeek(searchArea, true, 'search');
  var q = $input ? $input.value.trim() : '';
  renderLocalLibraryResults(q);
}
function formatProgramTime(sec) {
  sec = Math.max(0, Number(sec) || 0);
  var h = Math.floor(sec / 3600);
  var m = Math.floor((sec % 3600) / 60);
  var s = Math.floor(sec % 60);
  var mm = m < 10 ? ('0' + m) : String(m);
  var ss = s < 10 ? ('0' + s) : String(s);
  return h ? (h + ':' + mm + ':' + ss) : (m + ':' + ss);
}
$input.addEventListener('input', function(){
  clearTimeout(searchTimer);
  var q = $input.value.trim();
  if (!q) {
    renderLocalLibraryResults('');
    return;
  }
  $results.innerHTML = '<div class="search-empty">正在搜索 “' + escHtml(q) + '”…</div>';
  $results.classList.add('show');
  searchTimer = setTimeout(function(){ doSearch(q); }, searchInputDebounceMs());
});
$input.addEventListener('focus', function(){
  var searchArea = document.getElementById('search-area');
  if (searchArea) setPeek(searchArea, true, 'search');
  if (!$input.value.trim()) renderLocalLibraryResults('');
  else if (!$input.value.trim() && isMusicSearchMode(searchMode)) renderSearchHistory();
  else if ($results.children.length > 0) $results.classList.add('show');
});
var searchBoxEl = document.getElementById('search-box');
if (searchBoxEl) {
  searchBoxEl.addEventListener('click', function(){
    if ($input) $input.focus();
  });
}
$input.addEventListener('keydown', function(e){
  if (e.key === 'Enter') {
    e.preventDefault();
    clearTimeout(searchTimer);
    var q = $input.value.trim();
    if (isMusicSearchMode(searchMode) && q && playlist.length && searchLastResultQuery === searchResultKey(q)) $results.classList.add('show');
    else doSearch(q, { autoPlayFirst: false });
  } else if (e.key === 'Escape') {
    clearTimeout(searchTimer);
    $input.blur();
    clearSearchResults();
    if (!emptyHomeActive) setPeek(document.getElementById('search-area'), false, 'search');
  }
});
