// ============================================================
//  主循环
// ============================================================
var prevTime = performance.now();
var renderPerfState = {
  mode: 'vsync',
  fps: 0,
  frames: 0,
  skipped: 0,
  longFrames: 0,
  sampleLongFrames: 0,
  sampleWorstFrameMs: 0,
  pressureLevel: 0,
  pressureScore: 0,
  pressureReason: '',
  backgroundDelayScale: 1,
  lastRenderAt: 0,
  lastSampleAt: performance.now()
};
window.__mineradioPerf = renderPerfState;
var mainRenderFrameId = 0;
var mainRenderScheduleKind = '';
var mainRenderLoopSuspended = false;
/**
 * 取消主场景当前的调度句柄，兼容空闲定时器和交互态 RAF 两种调度方式。
 * @returns {void}
 */
function cancelMainRenderFrame() {
  if (!mainRenderFrameId) return;
  if (mainRenderScheduleKind === 'idle-timeout') clearTimeout(mainRenderFrameId);
  else cancelAnimationFrame(mainRenderFrameId);
  mainRenderFrameId = 0;
  mainRenderScheduleKind = '';
}
/**
 * 根据当前渲染状态选择调度类型；可见无播放空闲态用定时器避免每个显示器刷新周期都进入 JS 回调。
 * @param {number} [frameFps] 当前帧已计算的目标帧率；省略时从当前运行状态回退计算。
 * @returns {string} 当前应使用的调度类型。
 */
function mainRenderScheduleKindForState(frameFps) {
  var fps = frameFps == null && typeof getAdaptiveRenderFps === 'function' ? getAdaptiveRenderFps() : frameFps;
  return fps === RENDER_IDLE_FPS ? 'idle-timeout' : 'raf';
}
/**
 * 调度下一次主场景更新。空闲态按目标帧率唤醒，播放或交互态恢复 RAF。
 * @param {number} [frameFps] 当前帧已计算的目标帧率；省略时保留事件入口的回退读取。
 * @returns {boolean} 是否创建了新的调度句柄。
 */
function scheduleMainRenderFrame(frameFps) {
  if (mainRenderLoopSuspended || isDeepBackgroundMode()) return false;
  var scheduleKind = mainRenderScheduleKindForState(frameFps);
  if (mainRenderFrameId && mainRenderScheduleKind === scheduleKind) return false;
  if (mainRenderFrameId) cancelMainRenderFrame();
  mainRenderScheduleKind = scheduleKind;
  if (scheduleKind === 'idle-timeout') {
    mainRenderFrameId = setTimeout(function() {
      mainRenderFrameId = 0;
      mainRenderScheduleKind = '';
      animate();
    }, Math.max(16, Math.round(1000 / RENDER_IDLE_FPS)));
  } else {
    mainRenderFrameId = requestAnimationFrame(function() {
      mainRenderFrameId = 0;
      mainRenderScheduleKind = '';
      animate();
    });
  }
  return true;
}
function suspendMainRenderLoop(reason) {
  mainRenderLoopSuspended = true;
  cancelMainRenderFrame();
  renderPerfState.mode = 'suspended';
  renderPerfState.lastRenderAt = 0;
  if (reason && window.__mineradioDebugRenderPower) console.log('[RenderSuspended]', reason);
}
function resumeMainRenderLoop(reason) {
  if (isDeepBackgroundMode()) return false;
  var wasSuspended = mainRenderLoopSuspended;
  mainRenderLoopSuspended = false;
  if (wasSuspended || !mainRenderFrameId) {
    prevTime = performance.now();
    renderPerfState.lastRenderAt = 0;
  }
  var scheduled = scheduleMainRenderFrame();
  if (scheduled && reason && window.__mineradioDebugRenderPower) console.log('[RenderResumed]', reason);
  return scheduled;
}
function syncMainRenderLoopPowerState(reason) {
  if (typeof renderPerfState === 'undefined' || !renderPerfState) return;
  if (isDeepBackgroundMode()) suspendMainRenderLoop(reason || 'deep-background');
  else resumeMainRenderLoop(reason || 'foreground');
}
var splashWarmRenderLast = 0;
function isMainSceneCoveredBySplash() {
  return document.body.classList.contains('splash-active') && !document.body.classList.contains('splash-revealing');
}
/**
 * 判断当前是否存在需要高刷新率跟随的连续播放会话。
 * @returns {boolean} 音频正在输出且未结束时返回 true。
 */
function isContinuousPlaybackRenderActive() {
  return !!(audio && audio.src && !audio.paused && !audio.ended);
}
/**
 * 根据当前渲染压力、交互状态和后台状态选择主场景目标帧率。
 * @param {number} [frameNow] 当前帧时间戳；省略时由交互状态入口自行读取时钟。
 * @returns {number} 目标帧率；零表示跟随显示器 RAF。
 */
function getAdaptiveRenderFps(frameNow) {
  if (isDeepBackgroundMode()) return 1;
  var pressureLevel = (typeof getRuntimeFramePressureLevel === 'function') ? getRuntimeFramePressureLevel() : 0;
  var interactionActive = typeof isRenderInteractionActive === 'function' && isRenderInteractionActive(frameNow);
  if (RENDER_VISIBLE_VSYNC) {
    if (pressureLevel >= 2) return interactionActive ? 60 : 48;
    if (pressureLevel >= 1 && !interactionActive) return 60;
    if (!interactionActive && !isContinuousPlaybackRenderActive()) return RENDER_IDLE_FPS;
    return 0;
  }
  var tier = (typeof getRenderLoadTier === 'function') ? getRenderLoadTier() : 0;
  if (interactionActive) {
    if (tier >= 2) return RENDER_INTERACTION_HUGE_FPS;
    if (tier >= 1) return RENDER_INTERACTION_LARGE_FPS;
    return RENDER_INTERACTION_FPS;
  }
  if (tier >= 2) return RENDER_HUGE_FPS;
  if (tier >= 1) return RENDER_LARGE_FPS;
  return RENDER_ACTIVE_FPS;
}
/**
 * 判断当前调度回调是否早于目标帧率，并同步下一帧的节流状态。
 * @param {number} now 当前调度回调的 performance.now() 时间戳。
 * @param {number} [frameFps] 当前帧已计算的目标帧率；省略时回退计算。
 * @returns {boolean} 当前回调无需执行完整渲染时返回 true。
 */
function shouldSkipAdaptiveRenderFrame(now, frameFps) {
  var fps = frameFps == null ? getAdaptiveRenderFps(now) : frameFps;
  renderPerfState.mode = fps ? (fps + 'fps') : 'vsync';
  if (!fps) {
    renderPerfState.lastRenderAt = now;
    return false;
  }
  var minGap = 1000 / fps;
  if (now - renderPerfState.lastRenderAt < minGap) {
    renderPerfState.skipped += 1;
    return true;
  }
  renderPerfState.lastRenderAt = now;
  return false;
}
/**
 * 累计一秒级渲染性能样本，并在采样边界执行低频运行时缓存回收。
 * @param {number} now 当前渲染帧时间戳。
 * @param {number} dt 当前有效渲染帧间隔，单位为秒。
 * @returns {void} 仅更新渲染性能状态和低频缓存回收副作用。
 */
function sampleRenderPerf(now, dt) {
  renderPerfState.frames += 1;
  var frameMs = dt * 1000;
  if (dt > 0.034) {
    renderPerfState.longFrames += 1;
    renderPerfState.sampleLongFrames += 1;
  }
  if (frameMs > renderPerfState.sampleWorstFrameMs) renderPerfState.sampleWorstFrameMs = frameMs;
  if (now - renderPerfState.lastSampleAt >= 1000) {
    var sampleFrames = renderPerfState.frames;
    var sampleLongFrames = renderPerfState.sampleLongFrames;
    var sampleWorstFrameMs = renderPerfState.sampleWorstFrameMs;
    renderPerfState.fps = Math.round(sampleFrames * 1000 / Math.max(1, now - renderPerfState.lastSampleAt));
    if (typeof updateRuntimeFramePressure === 'function') {
      runtimeFramePressureSample.frames = sampleFrames;
      runtimeFramePressureSample.fps = renderPerfState.fps;
      runtimeFramePressureSample.longFrames = sampleLongFrames;
      runtimeFramePressureSample.worstFrameMs = sampleWorstFrameMs;
      updateRuntimeFramePressure(now, runtimeFramePressureSample);
    }
    renderPerfState.frames = 0;
    renderPerfState.sampleLongFrames = 0;
    renderPerfState.sampleWorstFrameMs = 0;
    renderPerfState.lastSampleAt = now;
    // 缓存回收本身按秒级门槛运行，无需让每个渲染帧重复检查后台状态和时间间隔。
    maybeTrimRuntimeCaches(now);
  }
}
/**
 * 消费一次音频分析时间片。渲染可以跟随高刷屏运行，但频谱分析限制在固定帧率，避免高刷屏重复计算同一段音频。
 * @param {number} now 当前 performance.now() 时间。
 * @param {number} fallbackDt 首帧或计时重置时使用的渲染时间片。
 * @returns {number} 本次允许音频分析时返回分析时间片，否则返回 0。
 */
function consumeAudioAnalysisDelta(now, fallbackDt) {
  var minGap = 1000 / AUDIO_ANALYSIS_TARGET_FPS;
  if (!audioAnalysisLastAt) {
    audioAnalysisLastAt = now;
    return Math.max(0.001, fallbackDt || (1 / AUDIO_ANALYSIS_TARGET_FPS));
  }
  var elapsed = now - audioAnalysisLastAt;
  if (elapsed < minGap) return 0;
  audioAnalysisLastAt = now;
  return Math.min(elapsed / 1000, 0.08);
}
/**
 * 执行一次主场景调度回调，并复用本帧时间戳和目标帧率减少热路径重复计算。
 * @returns {void} 通过全局渲染器、场景和动画状态产生渲染副作用。
 */
function animate() {
  mainRenderFrameId = 0;
  mainRenderScheduleKind = '';
  if (isDeepBackgroundMode()) {
    suspendMainRenderLoop('deep-background-frame');
    return;
  }
  var now = performance.now();
  var frameFps = getAdaptiveRenderFps(now);
  scheduleMainRenderFrame(frameFps);
  if (shouldSkipAdaptiveRenderFrame(now, frameFps)) return;
  var dt = Math.min((now - prevTime) / 1000, 0.05);
  prevTime = now;
  sampleRenderPerf(now, dt);
  uniforms.uTime.value += dt;
  if (isMainSceneCoveredBySplash()) {
    if (now - splashWarmRenderLast > 520) {
      splashWarmRenderLast = now;
      renderer.render(scene, camera);
    }
    return;
  }
  pointerParallax.x += (pointerTarget.x - pointerParallax.x) * 0.040;
  pointerParallax.y += (pointerTarget.y - pointerParallax.y) * 0.040;

  // 频谱分析 — v7.1: 真正分离 kick 和人声
  // bin = sampleRate / fftSize = 44100/2048 ≈ 21.5Hz
  // kick 60-150Hz → bin 3-7 (用前 5 个 bin)
  // vocal 200-3000Hz → bin 9-140 (尽量不计入 bass/mid 的"鼓点"判断)
  // 真正的 mid 乐器/和声: 3000-6000Hz → bin 140-280
  // treble: 6000Hz+ → bin 280+
  beatOnsetFlag = false;
  var shouldAnalyzeAudio = !!(analyser && playing && audio && !audio.paused);
  var analysisDt = shouldAnalyzeAudio ? consumeAudioAnalysisDelta(now, dt) : 0;
  if (shouldAnalyzeAudio && analysisDt > 0) {
    if (audioCtx && audioCtx.state === 'suspended') resumeAudioAnalysis();
    analyser.getByteFrequencyData(frequencyData);
    analyser.getByteTimeDomainData(timeDomainData);
    var len = frequencyData.length;
    // 精确频段
    var kickEnd  = 7;                          // 60-150 Hz, 鼓 kick
    var vocalEnd = Math.min(len, 140);         // 200-3000 Hz, 人声主体
    var midEnd   = Math.min(len, 280);         // 3-6 kHz, 中高乐器
    // 累积
    var bKick = 0, mInst = 0, tHigh = 0, voc = 0, rms = 0;
    // 频谱桶连续且互斥，单次扫描可减少循环边界、TypedArray 索引和分支初始化开销。
    for (var i = 0; i < len; i++) {
      var frequencyValue = frequencyData[i];
      if (i < kickEnd) bKick += frequencyValue;
      else if (i < vocalEnd) voc += frequencyValue;
      else if (i < midEnd) mInst += frequencyValue;
      else tHigh += frequencyValue;
    }
    for (var j = 0; j < timeDomainData.length; j++) {
      rms += audioTimeDomainSquareLut[timeDomainData[j]];
    }
    bKick *= AUDIO_FREQUENCY_SCALE / kickEnd;
    voc *= AUDIO_FREQUENCY_SCALE / (vocalEnd - kickEnd);
    mInst *= AUDIO_FREQUENCY_SCALE / Math.max(1, midEnd - vocalEnd);
    tHigh *= AUDIO_FREQUENCY_SCALE / Math.max(1, len - midEnd);
    rms = Math.sqrt(rms / timeDomainData.length);

    // 动态峰值跟踪
    bassPeak = Math.max(bassPeak * 0.994, bKick, 0.030);
    midPeak  = Math.max(midPeak  * 0.993, mInst, 0.026);
    treblePeak = Math.max(treblePeak * 0.992, tHigh, 0.018);
    energyPeak = Math.max(energyPeak * 0.995, rms, 0.030);

    var rb = Math.min(1, Math.pow(bKick / Math.max(0.038, bassPeak * 0.66), 0.78));
    var rm = Math.min(1, Math.pow(mInst / Math.max(0.025, midPeak  * 0.70), 0.86));
    var rt = Math.min(1, Math.pow(tHigh / Math.max(0.020, treblePeak * 0.74), 0.92));
    var re = Math.min(1, Math.pow(rms / Math.max(0.034, energyPeak * 0.68), 0.82));

    var bassOnset = Math.max(0, rb - smoothBass);
    var energyOnset = Math.max(0, re - prevEnergy);
    prevEnergy = prevEnergy * 0.88 + re * 0.12;

    var realtimeBeat = processRealtimeBeatEngine(analysisDt, rms);
    if (realtimeBeat && realtimeBeat.hit) {
      var dj = djMode.active;
      var djMapCoversCurrentTime = !dj || !currentDjBeatMap || !currentDjBeatMap.partialUntilSec || !audio || (audio.currentTime || 0) <= currentDjBeatMap.partialUntilSec - 1.25;
      var djBeatMapReadyForCamera = dj && currentDjBeatMap && currentDjBeatMap.cameraBeats && currentDjBeatMap.cameraBeats.length >= 4 && djMapCoversCurrentTime;
      var beatMapReadyForCamera = dj ? djBeatMapReadyForCamera : (currentBeatMap && currentBeatMap.cameraBeats && currentBeatMap.cameraBeats.length >= 4);
      var waitingForBeatMap = dj ? !djBeatMapReadyForCamera : (!beatMapReadyForCamera && (!!beatMapBusy || !!beatAnalysisTimer || ((audio && audio.currentTime) || 0) < 18));
      var liveKickFrame = dj
        ? (realtimeBeat.low > 0.48 && rb > 0.38 && bassOnset > 0.055 && energyOnset > 0.010 && (realtimeBeat.lowDominance || 0) > 0.82)
        : (realtimeBeat.low > 0.50 && rb > 0.42 && bassOnset > 0.070 && energyOnset > 0.016);
      var liveStrongHit = dj
        ? (realtimeBeat.confidence > 0.60 && realtimeBeat.strength > 0.56 && realtimeBeat.score > 0.50 && liveKickFrame)
        : (realtimeBeat.confidence > 0.76 && realtimeBeat.strength > 0.70 && realtimeBeat.score > 0.56 && liveKickFrame);
      var liveTempoHit = dj
        ? (realtimeBeat.tempoAssist && realtimeBeat.confidence > 0.62 && realtimeBeat.strength > 0.52 && realtimeBeat.low > 0.48 && (liveKickFrame || bassOnset > 0.046))
        : (realtimeBeat.tempoAssist && realtimeBeat.confidence > 0.80 && realtimeBeat.strength > 0.66 && realtimeBeat.low > 0.50 && bassOnset > 0.052);
      var liveFallbackOk = dj
        ? (liveStrongHit || liveTempoHit)
        : (waitingForBeatMap
          ? (liveStrongHit || liveTempoHit)
          : (realtimeBeat.confidence > 0.84 && realtimeBeat.strength > 0.80 && realtimeBeat.low > 0.54 && (liveKickFrame || realtimeBeat.score > 0.68)));
      if (!beatMapReadyForCamera && liveFallbackOk) {
        liveBeatCameraPayload.time = realtimeBeat.time;
        liveBeatCameraPayload.strength = realtimeBeat.strength;
        liveBeatCameraPayload.confidence = realtimeBeat.confidence;
        liveBeatCameraPayload.low = realtimeBeat.low;
        liveBeatCameraPayload.body = realtimeBeat.body;
        liveBeatCameraPayload.snap = realtimeBeat.snap;
        liveBeatCameraPayload.mass = realtimeBeat.mass;
        liveBeatCameraPayload.sharpness = realtimeBeat.sharpness;
        liveBeatCameraPayload.combo = realtimeBeat.combo;
        liveBeatCameraPayload.impact = clamp01(realtimeBeat.strength * 0.46 + realtimeBeat.confidence * 0.20 + realtimeBeat.low * 0.28);
        liveBeatCameraPayload.preview = waitingForBeatMap;
        liveBeatCameraPayload.primary = true;
        liveBeatCameraPayload.dj = dj;
        scheduleBeatCamera(liveBeatCameraPayload, 'live');
      }
      if (!beatMapReadyForCamera && liveFallbackOk) {
        var previewPulseScale = waitingForBeatMap && !dj ? 0.68 : 1;
        var rtPulse = Math.min(dj ? 0.34 : (waitingForBeatMap ? 0.46 : 0.62), realtimeBeat.strength * (realtimeBeat.tempoAssist ? (dj ? 0.42 : 0.62) : (dj ? 0.48 : 0.68)) * previewPulseScale);
        if (rtPulse > beatPulse + 0.09) beatOnsetFlag = true;
        beatPulse = Math.max(beatPulse, rtPulse);
      }
    } else if (bassOnset > 0.075 && rb > 0.32 && energyOnset > 0.020) {
      beatPulse = Math.max(beatPulse, Math.min(0.12, bassOnset * 0.18));
    }
    beatPulse *= Math.pow(0.36, analysisDt);

    // v7.2+: 预解析 beatmap 只在实时引擎暂时没锁住时补位.
    tickPodcastDjBeatMap();
    tickBeatMap();
    if (scheduledBeatFlag) {
      beatOnsetFlag = true;
      scheduledBeatFlag = false;
    }
    // scheduledBeatPulse 衰减并合并到 beatPulse
    if (scheduledBeatPulse > beatPulse) beatPulse = scheduledBeatPulse;
    scheduledBeatPulse *= Math.pow(0.32, analysisDt);

    // smoothBass 主要由 kick 驱动 (不被人声干扰)
    smoothBass  = smoothAnalysisEnvelope(smoothBass, Math.min(0.82, rb * 0.78 + re * 0.025), 0.28, 0.075);
    // smoothMid 用 中高乐器, 不再混入人声
    smoothMid   = smoothAnalysisEnvelope(smoothMid,  Math.min(0.68, rm * 0.64 + re * 0.025), 0.18, 0.060);
    smoothTreb  = smoothAnalysisEnvelope(smoothTreb, Math.min(0.56, rt * 0.54), 0.18, 0.055);
    smoothEnergy= smoothAnalysisEnvelope(smoothEnergy, Math.min(0.72, re), 0.16, 0.055);
    updateCinemaDynamics(re, rb);
    cinemaTrackProfileSample.energy = re;
    cinemaTrackProfileSample.low = rb;
    cinemaTrackProfileSample.vocal = voc;
    cinemaTrackProfileSample.melody = rm;
    cinemaTrackProfileSample.lowOnset = bassOnset;
    cinemaTrackProfileSample.energyOnset = energyOnset;
    updateCinemaTrackProfile(cinemaTrackProfileSample);
    // 歌词阳光溢光: 独立于律动强度, 看持续能量 + 中高频抬升, 更像副歌/高音段落而不是单个鼓点.
    var sunEnergy = clamp01((smoothEnergy - 0.18) / 0.38);
    var sunVoice = clamp01((voc - 0.11) / 0.34);
    var sunMelody = clamp01((smoothMid - 0.16) / 0.27);
    var sunAir = clamp01((smoothTreb - 0.105) / 0.17);
    var sunRaw = clamp01(sunEnergy * 0.36 + sunVoice * 0.18 + sunMelody * 0.26 + sunAir * 0.20);
    sunRaw = sunRaw * sunRaw * (3 - 2 * sunRaw);
    lyricSunAvg += (sunRaw - lyricSunAvg) * 0.006;
    lyricSunPeak = Math.max(0.48, lyricSunPeak * 0.9985, sunRaw);
    var sunThreshold = Math.max(0.78, lyricSunAvg + 0.20, lyricSunPeak * 0.74);
    var sunGate = clamp01((sunRaw - sunThreshold) / Math.max(0.08, 1.0 - sunThreshold));
    sunGate = sunGate * sunGate * (3 - 2 * sunGate);
    lyricSunHold += (sunGate - lyricSunHold) * (sunGate > lyricSunHold ? 0.035 : 0.014);
    lyricSunTarget = lyricSunHold > 0.16 ? clamp01((lyricSunHold - 0.16) / 0.84) : 0;
    lyricSunEnergy += (lyricSunTarget - lyricSunEnergy) * (lyricSunTarget > lyricSunEnergy ? 0.075 : 0.030);
  } else if (!shouldAnalyzeAudio) {
    audioAnalysisLastAt = 0;
    smoothBass *= 0.91; smoothMid *= 0.91; smoothTreb *= 0.91; smoothEnergy *= 0.91; beatPulse *= 0.82;
    liveCamAvg *= 0.94;
    liveCamPeak = Math.max(0.28, liveCamPeak * 0.98);
    liveCamLastRaw *= 0.80;
    lyricSunTarget = 0;
    lyricSunHold *= 0.90;
    lyricSunEnergy *= 0.92;
    lyricSunAvg *= 0.995;
    lyricSunPeak = Math.max(0.48, lyricSunPeak * 0.997);
  }
  audioEnergy = Math.max(smoothEnergy, beatPulse * 0.30);
  bass = Math.min(0.90, smoothBass * 1.05 + beatPulse * 0.18) * fx.intensity;
  mid  = Math.min(0.72, smoothMid * 1.12) * fx.intensity;
  treble = Math.min(0.62, smoothTreb * 1.20) * fx.intensity;
  if (fx.preset >= 4) {
    var wallpaperAudio = fx.preset === 5;
    var ringBass = smoothBass * (wallpaperAudio ? 1.10 : 1.58) + beatPulse * (wallpaperAudio ? 0.18 : 0.42) - smoothMid * 0.16 - smoothTreb * 0.06;
    var ringMid = smoothMid * (wallpaperAudio ? 1.16 : 1.82) - smoothBass * 0.14 - smoothTreb * 0.07;
    var ringTreble = smoothTreb * (wallpaperAudio ? 1.34 : 2.28) - smoothMid * 0.10 - smoothBass * 0.05;
    bass = Math.pow(clamp01((ringBass - 0.050) / 0.58), 0.72) * fx.intensity;
    mid = Math.pow(clamp01((ringMid - 0.045) / 0.46), 0.78) * fx.intensity;
    treble = Math.pow(clamp01((ringTreble - 0.030) / 0.34), 0.84) * fx.intensity;
    if (wallpaperAudio) {
      bass = Math.min(bass, 0.46 * fx.intensity);
      mid = Math.min(mid, 0.40 * fx.intensity);
      treble = Math.min(treble, 0.36 * fx.intensity);
      beatPulse *= 0.34;
    }
  }
  if (djMode.active) {
    bass = Math.min(1.00, bass * 1.06 + beatPulse * 0.085);
    mid = Math.min(0.76, mid * 1.00 + clamp01(djMode.sectionChange * 1.6) * 0.020);
    treble = Math.min(0.66, treble * 0.98);
    audioEnergy = Math.max(audioEnergy, beatPulse * 0.38, djMode.sectionEnergy * 0.54);
  }

  var vinylSpeedMul = isFinite(fx.speed) ? Math.max(0.05, fx.speed) : 1;
  var vinylSpinSpeed = (0.40 + smoothBass * 0.09) * vinylSpeedMul;
  uniforms.uVinylSpin.value = (uniforms.uVinylSpin.value + dt * vinylSpinSpeed) % (Math.PI * 2);

  updateParticlePointerFrame();
  uniforms.uBass.value   = bass;
  uniforms.uMid.value    = mid;
  uniforms.uTreble.value = treble;
  uniforms.uBeat.value   = beatPulse;
  uniforms.uEnergy.value = audioEnergy;
  uniforms.uMouseXY.value.set(mouseWorld.x, mouseWorld.y);
  uniforms.uMouseActive.value = mouseActive ? 1 : 0;
  // 通用转场脉冲: 只作为切换预设时的短促提亮。
  uniforms.uBurstAmt.value *= 0.90;
  tickPresetTransition();

  updateRipples(dt);
  var frameShelfState = refreshShelfRenderFrameState();
  if (shelfManager) shelfManager.update(dt, now, frameShelfState);
  // 歌单架更新会推进可见度；组合状态复用同一份 getter 快照，只重新计算依赖可见度的布尔值。
  frameShelfState.skullComposition = !!(fx && fx.preset === SKULL_PRESET_INDEX && frameShelfState.side && (shelfPinnedOpen || shelfVisibility > 0.18 || frameShelfState.contentOpen));
  var skullBackdropDim = fx && fx.preset === SKULL_PRESET_INDEX ? 0.58 : 1;
  var shelfDimTarget = shouldDimWallpaperForShelf(frameShelfState) ? 0.48 : skullBackdropDim;
  var shelfDimEase = shelfDimTarget < uniforms.uParticleDim.value ? 0.18 : 0.10;
  uniforms.uParticleDim.value += (shelfDimTarget - uniforms.uParticleDim.value) * Math.min(1, shelfDimEase * Math.max(1, dt * 60));
  tickLyricsParticles();
  updateHomeAudioVisual(dt, now);

  // 电影镜头
  updateCinema(dt);
  updateFreeCamera(dt, now);
  updateCamera();
  applySkullCameraPose(dt, frameShelfState);

  // v7.2 旋转 = 头部+眼球追踪 + 鼠标/手势拖动 + 惯性
  tickGestureRotation(dt, now);
  var skullPresetActive = fx && fx.preset === SKULL_PRESET_INDEX;
  particles.visible = !skullPresetActive;
  if (bloomParticles) bloomParticles.visible = !skullPresetActive && fx.bloom && fx.bloomStrength > 0.01;
  if (floatGroup) floatGroup.visible = !skullPresetActive;
  if (backCoverGroup) backCoverGroup.visible = !skullPresetActive;
  var targetRotY = orbit.centerLocked ? 0 : (headParallax.active ? headParallax.x * 0.5 : 0) + gestureRotation.y;
  var targetRotX = orbit.centerLocked ? 0 : (headParallax.active ? -headParallax.y * 0.35 : 0) + gestureRotation.x;
  particles.rotation.y += (targetRotY - particles.rotation.y) * 0.055;
  particles.rotation.x += (targetRotX - particles.rotation.x) * 0.055;
  if (bloomParticles) {
    bloomParticles.rotation.copy(particles.rotation);
  }
  // 同步给背面粒子层
  if (floatGroup) {
    floatGroup.rotation.copy(particles.rotation);
  }
  if (backCoverGroup) {
    backCoverGroup.rotation.copy(particles.rotation);
  }
  updateSkullParticleLayer(dt, frameShelfState);
  updateStageLyrics3D(dt, frameShelfState);

  renderer.render(scene, camera);
}
resumeMainRenderLoop('startup');
